-- set: Demo Mini Set (30 cards)
insert into cps.card_sets (id, name, code, pack, card_count, active, updated_at)
values ('demo-mini', 'Demo Mini Set', 'DMO', '{"name":"Booster Pack","slots":[{"count":5,"label":"Common","odds":{"common":1}},{"count":2,"label":"Uncommon","odds":{"uncommon":1}},{"count":1,"label":"Wild card","odds":{"common":0.55,"uncommon":0.3,"rare":0.12,"epic":0.03}},{"count":1,"label":"Rare or better (guaranteed)","odds":{"rare":0.818,"epic":0.14,"legendary":0.042}}],"holo":{"common":2,"uncommon":3,"rare":6,"epic":10,"legendary":15,"chase":25}}'::jsonb, 30, true, now())
on conflict (id) do update set name = excluded.name, code = excluded.code, pack = excluded.pack, card_count = excluded.card_count, active = true, updated_at = now();
